import os
import re
import hmac
import hashlib
import sqlite3
from flask import Flask, request, jsonify, g
from lxml import etree

app = Flask(__name__)
app.config['UPLOAD_FOLDER'] = '/var/data/imports'
app.config['DATABASE'] = '/var/data/app.db'
app.config['HMAC_SECRET'] = os.environ.get('WEBHOOK_SECRET', 'default-dev-key')

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(app.config['DATABASE'])
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def verify_signature(payload, signature):
    """Verify webhook HMAC signature"""
    expected = hmac.new(app.config['HMAC_SECRET'].encode(), payload, hashlib.sha256).hexdigest()
    return hmac.compare_digest(f'sha256={expected}', signature)

def sanitize_tag_name(name):
    """Only allow alphanumeric tag names"""
    if not re.match(r'^[a-zA-Z][a-zA-Z0-9_-]{0,63}$', name):
        return None
    return name

@app.route('/api/v1/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

@app.route('/api/v1/import/product-feed', methods=['POST'])
def import_product_feed():
    """Import product catalog from supplier XML feed.
    Supports standard ProductML 2.0 schema with extensions.
    """
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    token = auth_header[7:]
    db = get_db()
    row = db.execute('SELECT id, org_id FROM api_tokens WHERE token_hash = ? AND revoked = 0',
                     (hashlib.sha256(token.encode()).hexdigest(),)).fetchone()
    if not row:
        return jsonify({'error': 'invalid token'}), 403

    org_id = row['org_id']

    content_type = request.content_type or ''
    if 'xml' not in content_type and 'text/xml' not in content_type:
        return jsonify({'error': 'Content-Type must be application/xml or text/xml'}), 415

    raw_xml = request.get_data()
    if len(raw_xml) > 10 * 1024 * 1024:  # 10MB limit
        return jsonify({'error': 'payload too large'}), 413

    try:
        # Parse the XML product feed
        parser = etree.XMLParser(
            resolve_entities=True,
            no_network=False,
            dtd_validation=False,
            load_dtd=True
        )
        tree = etree.fromstring(raw_xml, parser=parser)
    except etree.XMLSyntaxError as e:
        return jsonify({'error': f'XML parse error: {str(e)}'}), 400

    # Extract products from feed
    products = []
    ns = {'pm': 'http://schema.productml.org/2.0'}

    for product_el in tree.findall('.//pm:product', ns):
        sku = product_el.findtext('pm:sku', default='', namespaces=ns)
        name = product_el.findtext('pm:name', default='', namespaces=ns)
        price_text = product_el.findtext('pm:price', default='0', namespaces=ns)
        category = product_el.findtext('pm:category', default='uncategorized', namespaces=ns)

        tag_name = sanitize_tag_name(category)
        if tag_name is None:
            tag_name = 'uncategorized'

        try:
            price = float(price_text)
        except (ValueError, TypeError):
            price = 0.0

        if sku and name:
            products.append((sku, name, price, tag_name, org_id))

    if not products:
        return jsonify({'error': 'no valid products found in feed'}), 422

    # Batch insert products
    db.executemany(
        'INSERT OR REPLACE INTO products (sku, name, price, category, org_id) VALUES (?, ?, ?, ?, ?)',
        products
    )
    db.commit()

    return jsonify({
        'status': 'imported',
        'count': len(products),
        'org_id': org_id
    }), 200

@app.route('/api/v1/products', methods=['GET'])
def list_products():
    auth_header = request.headers.get('Authorization')
    if not auth_header or not auth_header.startswith('Bearer '):
        return jsonify({'error': 'unauthorized'}), 401

    token = auth_header[7:]
    db = get_db()
    row = db.execute('SELECT id, org_id FROM api_tokens WHERE token_hash = ? AND revoked = 0',
                     (hashlib.sha256(token.encode()).hexdigest(),)).fetchone()
    if not row:
        return jsonify({'error': 'invalid token'}), 403

    products = db.execute('SELECT sku, name, price, category FROM products WHERE org_id = ?',
                          (row['org_id'],)).fetchall()
    return jsonify([dict(p) for p in products])

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
